"""Run the offline evaluation harness and write docs/EVAL_REPORT.md + data/eval/report.json.
Usage: .venv/Scripts/python scripts/run_eval.py"""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from panch.eval import run  # noqa: E402

res = run()
s = res["summary"]
out = ROOT / "data" / "eval"
out.mkdir(parents=True, exist_ok=True)
(out / "report.json").write_text(json.dumps(res, indent=2, ensure_ascii=False), encoding="utf-8")

lines = [
    "# Evaluation report (generated by `scripts/run_eval.py`)", "",
    f"{s['cases']} cases built by mutating the clean demo invoices (A, B, C, H): {s['clean']} clean controls "
    f"(including legitimate twins) and {s['traps']} planted traps. Bank checks use canned sandbox fixtures, offline.", "",
    "| Metric | Value |", "|---|---|",
    f"| Traps blocked | **{s['traps_blocked']}/{s['traps']}** (held for a question: {s['traps_held_ask']}, missed: {s['traps_missed_pay']}) |",
    f"| Traps caught by the expected reason code | {s['traps_with_expected_code']}/{s['traps']} |",
    f"| Clean auto-paid | **{s['clean_auto_paid']}/{s['clean']}** |",
    f"| Clean falsely held (ASK) | **{s['clean_falsely_held']}** |",
    f"| Clean false blocks | {s['clean_false_blocks']} |", "",
    f"Claim: {s['claim']}. This is our own synthetic set, not the organisers' unseen batch.", "",
    "| Case | Kind | What | Expected code | Outcome | Codes |", "|---|---|---|---|---|---|",
]
for r in res["rows"]:
    lines.append(f"| {r['case']} | {r['kind']} | {r['what']} | {r['expect_code'] or ''} | {r['outcome']} | "
                 f"{', '.join(r['codes'])} |")
(ROOT / "docs" / "EVAL_REPORT.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
print(json.dumps(s, indent=2))
bad = [r for r in res["rows"] if (r["kind"] == "clean" and r["outcome"] != "PAY") or
       (r["kind"] == "trap" and r["outcome"] == "PAY")]
for r in bad:
    print("CHECK:", r["case"], r["outcome"], r["codes"])
